import { readdirSync, readFileSync, statSync, existsSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import ts from "typescript";

export interface ImportRef {
  /** repo-relative POSIX path of the importing file */
  readonly from: string;
  /** raw module specifier as written */
  readonly specifier: string;
  /** repo-relative POSIX path if the specifier resolves inside the repo, else null */
  readonly resolved: string | null;
  readonly line: number;
}

const SOURCE_EXT = [".ts", ".tsx", ".mts", ".cts"];
const IGNORED_DIRS = new Set([
  "node_modules",
  ".next",
  ".turbo",
  "dist",
  "coverage",
  ".git",
  "penpot",
  "_sprint2-transfer",
]);

export function repoRoot(startDir: string): string {
  let dir = resolve(startDir);
  for (;;) {
    if (existsSync(join(dir, "pnpm-workspace.yaml"))) return dir;
    const parent = dirname(dir);
    if (parent === dir) throw new Error(`pnpm-workspace.yaml not found above ${startDir}`);
    dir = parent;
  }
}

export function collectSourceFiles(dir: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir)) {
    if (IGNORED_DIRS.has(entry)) continue;
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) out.push(...collectSourceFiles(full));
    else if (st.isFile() && SOURCE_EXT.some((e) => entry.endsWith(e))) out.push(full);
  }
  return out;
}

function posix(p: string): string {
  return p.split(sep).join("/");
}

function resolveRelative(fromAbs: string, spec: string): string | null {
  const base = resolve(dirname(fromAbs), spec);
  const candidates = [
    base,
    ...SOURCE_EXT.map((e) => base + e),
    // ESM-Pakete importieren mit .js -> Quelle ist .ts/.tsx
    ...(base.endsWith(".js") ? SOURCE_EXT.map((e) => base.slice(0, -3) + e) : []),
    ...SOURCE_EXT.map((e) => join(base, "index" + e)),
  ];
  for (const c of candidates) {
    if (existsSync(c) && statSync(c).isFile()) return c;
  }
  return null;
}

export function extractImports(root: string, files: string[]): ImportRef[] {
  const refs: ImportRef[] = [];
  for (const abs of files) {
    const text = readFileSync(abs, "utf8");
    const info = ts.preProcessFile(text, true, true);
    for (const ref of info.importedFiles) {
      const spec = ref.fileName;
      const line = text.slice(0, ref.pos).split("\n").length;
      const resolvedAbs = spec.startsWith(".") ? resolveRelative(abs, spec) : null;
      refs.push({
        from: posix(relative(root, abs)),
        specifier: spec,
        resolved: resolvedAbs ? posix(relative(root, resolvedAbs)) : null,
        line,
      });
    }
  }
  return refs;
}

