import type { ImportRef } from "./scan.js";

export interface Violation {
  readonly rule: string;
  readonly file: string;
  readonly line: number;
  readonly specifier: string;
  readonly message: string;
}

export interface Rule {
  readonly id: string;
  /** Wieviele Dateien MUESSEN mindestens in den Geltungsbereich fallen (Nicht-Vakuitaet). */
  readonly minScopeFiles: number;
  scope(file: string): boolean;
  check(ref: ImportRef): string | null;
}

const FORBIDDEN_IN_DOMAIN = [
  /^@nestjs\//,
  /^express$/,
  /^@?fastify/,
  /^kysely$/,
  /^pg$/,
  /^pg-boss$/,
  /^@supabase\//,
  /^next$/,
  /^next\//,
  /^react$/,
  /^react-dom/,
  /^node:http$/,
  /^node:https$/,
  /^node:net$/,
  /^axios$/,
  /^node-fetch$/,
  /^reflect-metadata$/,
  /^@easytree\/(config|ui|contracts)$/,
];

const MODULE_FILE = /^apps\/api\/src\/modules\/([^/]+)\/(.*)$/;

function moduleOf(file: string): string | null {
  const m = MODULE_FILE.exec(file);
  return m?.[1] ?? null;
}

export const RULES: readonly Rule[] = [
  {
    id: "domain-framework-free",
    minScopeFiles: 1,
    scope: (f) =>
      /^packages\/domain\/src\//.test(f) ||
      /^apps\/api\/src\/modules\/[^/]+\/domain\//.test(f),
    check: (ref) =>
      FORBIDDEN_IN_DOMAIN.some((p) => p.test(ref.specifier))
        ? `Domainschicht importiert Framework/Infrastruktur "${ref.specifier}" (ADR-001 Z. 74).`
        : null,
  },
  {
    id: "module-public-api-only",
    minScopeFiles: 1,
    scope: (f) => MODULE_FILE.test(f),
    check: (ref) => {
      const own = moduleOf(ref.from);
      if (!ref.resolved) return null;
      const target = moduleOf(ref.resolved);
      if (target === null || own === null || target === own) return null;
      const isPublicApi = ref.resolved === `apps/api/src/modules/${target}/index.ts`;
      return isPublicApi
        ? null
        : `Querimport in Modul "${target}" umgeht dessen index.ts: ${ref.resolved} (ADR-001 Z. 76).`;
    },
  },
  {
    id: "no-app-to-app",
    minScopeFiles: 1,
    scope: (f) => f.startsWith("apps/"),
    check: (ref) => {
      const ownApp = /^apps\/([^/]+)\//.exec(ref.from)?.[1] ?? null;
      const byName = /^@easytree\/(api|web)$/.exec(ref.specifier)?.[1] ?? null;
      const byPath = ref.resolved ? (/^apps\/([^/]+)\//.exec(ref.resolved)?.[1] ?? null) : null;
      const target = byName ?? byPath;
      if (target === null || ownApp === null || target === ownApp) return null;
      return `App-zu-App-Import: apps/${ownApp} importiert apps/${target} ("${ref.specifier}").`;
    },
  },
  {
    id: "no-packages-shared",
    minScopeFiles: 1,
    scope: () => true,
    check: (ref) =>
      /(^|\/)packages\/shared(\/|$)/.test(ref.specifier) ||
      /^@easytree\/shared$/.test(ref.specifier) ||
      (ref.resolved !== null && ref.resolved.startsWith("packages/shared/"))
        ? `packages/shared ist verboten (ADR-001 Z. 77).`
        : null,
  },
];

export function evaluate(refs: readonly ImportRef[], files: readonly string[]) {
  const violations: Violation[] = [];
  const scopeCounts = new Map<string, number>();
  for (const rule of RULES) {
    scopeCounts.set(rule.id, files.filter((f) => rule.scope(f)).length);
    for (const ref of refs) {
      if (!rule.scope(ref.from)) continue;
      const message = rule.check(ref);
      if (message !== null) {
        violations.push({
          rule: rule.id,
          file: ref.from,
          line: ref.line,
          specifier: ref.specifier,
          message,
        });
      }
    }
  }
  return { violations, scopeCounts };
}

