import { describe, expect, it } from "vitest";
import { evaluate, RULES } from "./rules.js";
import { collectSourceFiles, extractImports, repoRoot } from "./scan.js";

function posix(p: string) {
  return p.split(sep).join("/");
}

const ROOT = repoRoot(new URL(".", import.meta.url).pathname);
const FIXTURES = new URL("./fixtures", import.meta.url).pathname;

describe("architecture boundaries — real repo", () => {
  const files = collectSourceFiles(ROOT)
    .map((f) => posix(relative(ROOT, f)))
    .filter((r) => (r.startsWith("apps/") || r.startsWith("packages/")) && !r.includes(".arch-proto"));
  const abs = files.map((r) => `${ROOT}/${r}`);
  const refs = extractImports(ROOT, abs);
  const { violations, scopeCounts } = evaluate(refs, files);

  it("scans a non-empty source set", () => {
    expect(files.length).toBeGreaterThan(20);
    expect(refs.length).toBeGreaterThan(20);
    // eslint-disable-next-line no-console
    console.log(
      `[architecture] files=${files.length} imports=${refs.length} violations=${violations.length}`,
    );
  });

  it("has no forbidden imports", () => {
    expect(violations.map((v) => `${v.file}:${v.line} [${v.rule}] ${v.message}`)).toEqual([]);
  });

  it("every rule has a non-empty scope", () => {
    console.log("[architecture] scope:", JSON.stringify([...scopeCounts]));
    for (const rule of RULES) {
      expect.soft(scopeCounts.get(rule.id) ?? 0).toBeGreaterThanOrEqual(rule.minScopeFiles);
    }
  });
});

describe("architecture checker — red case on fixtures", () => {
  const files = collectSourceFiles(FIXTURES).map((f) => posix(relative(FIXTURES, f)));
  const abs = files.map((r) => `${FIXTURES}/${r}`);
  const refs = extractImports(FIXTURES, abs);
  const { violations } = evaluate(refs, files);

  it("flags each rule at least once", () => {
    console.log(
      "[architecture-fixture]",
      violations.map((v) => `${v.rule}@${v.file}:${v.line}`).join(" | "),
    );
    const ids = new Set(violations.map((v) => v.rule));
    for (const rule of RULES) expect.soft([...ids]).toContain(rule.id);
  });

  it("does not flag the legal control files", () => {
    const flagged = new Set(violations.map((v) => v.file));
    expect(flagged.has("apps/api/src/modules/planning/domain/good.ts")).toBe(false);
    expect(flagged.has("apps/api/src/modules/workforce/index.ts")).toBe(false);
  });
});

