// apps/api/src/platform/table-ownership.ts
// Pure data. No NestJS / Kysely / pg / HTTP import, so module `domain/` layers may
// read it without violating ADR-001 Z. 74 ("Domain importiert keine Framework-
// oder Infrastrukturpakete").

export const MODULES = [
  "tenancy", "workforce", "worksites", "planning", "resources",
  "time", "absence", "audit", "notifications", "weather", "files",
] as const;
export type ModuleName = (typeof MODULES)[number];

/** Deliberate non-module owners. A table here is NOT a domain table. */
export const NON_MODULE_OWNERS = [
  "platform",         // apps/api/src/platform/** (Kysely/UnitOfWork, sprint plan Z. 311)
  "test-fixture",     // synthetic RLS-proof tables (items, item_notes)
  "supabase-managed", // auth.*, storage.* — never written by module code
] as const;
export type NonModuleOwner = (typeof NON_MODULE_OWNERS)[number];
export type TableOwner = ModuleName | NonModuleOwner;

export interface TableOwnership {
  /** fully qualified, byte-identical to the migration: '<schema>.<table>' */
  readonly table: `${string}.${string}`;
  readonly owner: TableOwner;
  /** modules allowed to SELECT but never write. Empty = owner only. */
  readonly readableBy: readonly ModuleName[];
  /** true => org_id NOT NULL (ADR-001 Z. 82). false REQUIRES `note`. */
  readonly tenantOwned: boolean;
  /** migration filename that CREATEs it — greppable, drift-checkable */
  readonly introducedIn: string;
  /** mandatory when tenantOwned === false or owner is a NonModuleOwner.
   *  exactOptionalPropertyTypes: never assign `undefined` explicitly — omit the key. */
  readonly note?: string;
}

export const TABLE_OWNERSHIP = [
  { table: "public.organizations", owner: "tenancy", readableBy: [], tenantOwned: false,
    introducedIn: "20260723214800_0001_foundation.sql",
    note: "IST der Mandant; hat naturgemaess kein org_id (Sprint-3-Plan Z. 338-339)." },
  { table: "public.users", owner: "tenancy", readableBy: [], tenantOwned: false,
    introducedIn: "20260723222457_0002_tenancy.sql",
    note: "1:1 auf auth.users, RLS nur self; Org-Zuordnung nur ueber memberships." },
  { table: "public.memberships", owner: "tenancy", readableBy: [], tenantOwned: true,
    introducedIn: "20260723222457_0002_tenancy.sql" },
  { table: "public.items", owner: "test-fixture", readableBy: [], tenantOwned: true,
    introducedIn: "20260723222457_0002_tenancy.sql",
    note: "RLS-Beweisfixture. Genutzt von supabase/tests/0002_rls_isolation.sql und den " +
          "Tenant-Integrationstests — Entfernen bricht das Pflicht-Gate db-gates." },
  { table: "public.item_notes", owner: "test-fixture", readableBy: [], tenantOwned: true,
    introducedIn: "20260723222457_0002_tenancy.sql",
    note: "wie public.items; belegt den tenantgebundenen Composite-FK." },
] as const satisfies readonly TableOwnership[];
// `as const satisfies` keeps the literal types (needed by TablesOwnedBy below)
// while still type-checking every entry against TableOwnership.

/** COMPILE-TIME projection: which tables may module M write? */
export type TablesOwnedBy<M extends ModuleName> =
  Extract<(typeof TABLE_OWNERSHIP)[number], { owner: M }>["table"];

// noUncheckedIndexedAccess: Map.get() is `T | undefined`, so the lookup fails
// closed with a throw instead of silently returning undefined.
const BY_TABLE: ReadonlyMap<string, TableOwnership> =
  new Map(TABLE_OWNERSHIP.map((e) => [e.table, e] as const));

export function ownerOf(table: string): TableOwner {
  const entry = BY_TABLE.get(table);
  if (entry === undefined) {
    throw new Error(`Tabelle ${table} hat keinen Registry-Eintrag (fail closed).`);
  }
  return entry.owner;
}
export function mayWrite(module: ModuleName, table: string): boolean {
  return ownerOf(table) === module;
}

