/**
 * Architekturregeln als Daten (EYT-46).
 *
 * Zwei Entwurfsentscheidungen, beide aus der kritischen Prüfung des Entwurfs:
 *
 * 1. `domain-allowlist` ist eine **Allowlist**, keine Blockliste. ADR-001 Z. 74
 *    („Domain importiert keine Framework- oder Infrastrukturpakete") ist ein
 *    universelles Verbot; eine endliche Liste verbotener Pakete kann das nie
 *    ausdrücken. Belegte Gegenbeispiele einer Blockliste: `http` (statt
 *    `node:http`), `pg-pool` (statt `pg`), `kysely/dist/esm/index.js` (statt
 *    `kysely`), dazu `rxjs`, das eine echte Abhängigkeit von `@easytree/api`
 *    ist. Erlaubt ist deshalb nur, was ausdrücklich genannt ist.
 *
 * 2. Der Geltungsbereich von `module-public-api-only` ist **ganz**
 *    `apps/api/src/**`, nicht nur `apps/api/src/modules/**`. Sonst dürfte
 *    ausgerechnet die Kompositionswurzel `app.module.ts` in jedes
 *    `infrastructure/` greifen — der wahrscheinlichste reale Verstoss in einer
 *    NestJS-Anwendung.
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import type { ImportRef } from "./scan";

export interface Violation {
  readonly rule: string;
  readonly file: string;
  readonly line: number;
  readonly message: string;
}

export interface Rule {
  readonly id: string;
  /** Trifft zu, wenn die Datei von dieser Regel überwacht wird. */
  readonly inScope: (file: string) => boolean;
  readonly check: (ref: ImportRef) => string | null;
}

const API_MODULES = "apps/api/src/modules/";
const DOMAIN_PACKAGE = "packages/domain/src/";

/** `apps/api/src/modules/<slug>/…` -> `<slug>`, sonst null. */
export function moduleOf(file: string): string | null {
  if (!file.startsWith(API_MODULES)) return null;
  const rest = file.slice(API_MODULES.length);
  const slash = rest.indexOf("/");
  if (slash <= 0) return null;
  return rest.slice(0, slash);
}

/** `apps/<name>/…` -> `<name>`, sonst null. */
function appOf(file: string): string | null {
  if (!file.startsWith("apps/")) return null;
  const rest = file.slice("apps/".length);
  const slash = rest.indexOf("/");
  return slash > 0 ? rest.slice(0, slash) : null;
}

/** Schicht innerhalb eines Moduls, sonst null. */
function layerOf(file: string): string | null {
  const module = moduleOf(file);
  if (module === null) return null;
  const rest = file.slice(API_MODULES.length + module.length + 1);
  const slash = rest.indexOf("/");
  return slash > 0 ? rest.slice(0, slash) : null;
}

const LAYER_RANK: Record<string, number> = {
  domain: 0,
  application: 1,
  infrastructure: 2,
  interface: 3,
};

/** Unspezifische Sammelpakete. ADR-001 Z. 77 verbietet die Sache, nicht nur den Namen. */
const GENERIC_PACKAGE_NAMES = ["shared", "common", "utils", "util", "misc", "core", "helpers", "lib"];

function isDomainFile(file: string): boolean {
  return file.startsWith(DOMAIN_PACKAGE) || layerOf(file) === "domain";
}

export const RULES: readonly Rule[] = [
  {
    // ADR-001 Z. 74 — als Allowlist formuliert, siehe Dateikopf.
    id: "domain-allowlist",
    inScope: isDomainFile,
    check: (ref): string | null => {
      if (ref.isTypeReference) {
        return `Domaincode darf keine /// <reference types="${ref.specifier}" /> fuehren — sie zieht eine ganze Ambient-Oberflaeche in den Scope.`;
      }
      if (ref.specifier === "@easytree/domain") return null;
      if (!ref.specifier.startsWith(".")) {
        return `Domaincode darf "${ref.specifier}" nicht importieren. Erlaubt sind ausschliesslich relative Pfade innerhalb der eigenen domain/-Schicht und "@easytree/domain" (ADR-001 Z. 74).`;
      }
      if (ref.resolved === null) {
        return `Relativer Import "${ref.specifier}" ist nicht aufloesbar — der Scanner koennte ihn sonst stillschweigend uebergehen.`;
      }
      if (!isDomainFile(ref.resolved)) {
        return `Domaincode darf nicht nach "${ref.resolved}" hinausgreifen; das liegt ausserhalb einer domain/-Schicht (ADR-001 Z. 74).`;
      }
      const fromModule = moduleOf(ref.from);
      const toModule = moduleOf(ref.resolved);
      if (fromModule !== toModule) {
        return `Domaincode von "${fromModule ?? "packages/domain"}" darf nicht in die domain/-Schicht von "${toModule ?? "packages/domain"}" greifen (ADR-001 Z. 76).`;
      }
      return null;
    },
  },
  {
    // ADR-001 Z. 76 — modulübergreifend nur über die öffentliche index.ts.
    id: "module-public-api-only",
    inScope: (file): boolean => file.startsWith("apps/api/src/"),
    check: (ref): string | null => {
      if (ref.resolved === null) return null;
      const toModule = moduleOf(ref.resolved);
      if (toModule === null) return null;
      const fromModule = moduleOf(ref.from);
      if (fromModule === toModule) return null;
      const publicApi = `${API_MODULES}${toModule}/index.ts`;
      if (ref.resolved === publicApi) return null;
      return `Zugriff auf Modul "${toModule}" nur ueber ${publicApi}, nicht ueber "${ref.resolved}" (ADR-001 Z. 76).`;
    },
  },
  {
    // Schichtrichtung innerhalb eines Moduls (ADR-001 Z. 65-69).
    id: "layer-direction",
    inScope: (file): boolean => layerOf(file) !== null,
    check: (ref): string | null => {
      if (ref.resolved === null) return null;
      if (moduleOf(ref.from) !== moduleOf(ref.resolved)) return null;
      const fromLayer = layerOf(ref.from);
      const toLayer = layerOf(ref.resolved);
      if (fromLayer === null || toLayer === null) return null;
      const fromRank = LAYER_RANK[fromLayer];
      const toRank = LAYER_RANK[toLayer];
      if (fromRank === undefined || toRank === undefined) return null;
      if (toRank <= fromRank) return null;
      return `Schicht "${fromLayer}" darf nicht nach "${toLayer}" importieren — erlaubt ist nur von aussen nach innen (ADR-001 Z. 65-69).`;
    },
  },
  {
    // Keine App-zu-App-Kopplung; Pakete duerfen ueberhaupt keine App importieren.
    id: "no-app-to-app",
    inScope: (file): boolean => file.startsWith("apps/") || file.startsWith("packages/"),
    check: (ref): string | null => {
      if (/^@easytree\/(api|web)$/.test(ref.specifier)) {
        const own = appOf(ref.from);
        if (own === null || `@easytree/${own}` !== ref.specifier) {
          return `"${ref.specifier}" ist eine Anwendung, kein Paket — Anwendungen duerfen einander nicht importieren.`;
        }
        return null;
      }
      if (ref.resolved === null) return null;
      const toApp = appOf(ref.resolved);
      if (toApp === null) return null;
      if (ref.from.startsWith("packages/")) {
        return `Paketcode darf nicht nach "${ref.resolved}" in eine Anwendung greifen.`;
      }
      const fromApp = appOf(ref.from);
      if (fromApp !== null && fromApp !== toApp) {
        return `Anwendung "${fromApp}" darf nicht nach "${ref.resolved}" in Anwendung "${toApp}" greifen.`;
      }
      return null;
    },
  },
  {
    // ADR-001 Z. 77 — nicht nur der Name `shared`, sondern das Muster.
    id: "no-generic-shared-package",
    inScope: (): boolean => true,
    check: (ref): string | null => {
      const scoped = /^@easytree\/([a-z-]+)$/.exec(ref.specifier);
      const name = scoped?.[1];
      if (name !== undefined && GENERIC_PACKAGE_NAMES.includes(name)) {
        return `"${ref.specifier}" ist ein unspezifisches Sammelpaket. ADR-001 Z. 77 erlaubt nur stabile, fachlich benannte Pakete.`;
      }
      if (ref.resolved !== null) {
        const pkg = /^packages\/([a-z-]+)\//.exec(ref.resolved);
        const dir = pkg?.[1];
        if (dir !== undefined && GENERIC_PACKAGE_NAMES.includes(dir)) {
          return `"packages/${dir}" ist ein unspezifisches Sammelpaket (ADR-001 Z. 77).`;
        }
      }
      return null;
    },
  },
  {
    // ADR-002 §5 — Prototype-Fixtures sind ausschliesslich Clickdummy-/Testdaten.
    id: "no-fixtures-in-production-code",
    inScope: (file): boolean => !/(^|\/)(test|e2e|__tests__)\//.test(file),
    check: (ref): string | null =>
      ref.specifier === "@easytree/prototype-fixtures" ||
      ref.resolved?.startsWith("packages/prototype-fixtures/") === true
        ? `Produktionscode darf "${ref.specifier}" nicht importieren — Prototype-Fixtures sind ausschliesslich Clickdummy-/Testdaten (ADR-002 §5).`
        : null,
  },
];

export function evaluate(refs: readonly ImportRef[]): {
  violations: Violation[];
  scopeCounts: Map<string, Set<string>>;
} {
  const violations: Violation[] = [];
  const scopeCounts = new Map<string, Set<string>>();

  for (const rule of RULES) scopeCounts.set(rule.id, new Set<string>());

  for (const ref of refs) {
    for (const rule of RULES) {
      if (!rule.inScope(ref.from)) continue;
      scopeCounts.get(rule.id)?.add(ref.from);
      const message = rule.check(ref);
      if (message !== null) {
        violations.push({ rule: rule.id, file: ref.from, line: ref.line, message });
      }
    }
  }

  return { violations, scopeCounts };
}

/**
 * `export *` in einer Modul-`index.ts` traegt das gesamte Domainmodell ueber die
 * Grenze und macht aus mehreren Modulen ein globales Modell (EYT-46 AK 5).
 * Benannte Re-Exporte sind der Vertrag; ein Stern ist keiner.
 */
export function findStarReExports(repoRoot: string, files: readonly string[]): Violation[] {
  const out: Violation[] = [];
  for (const file of files) {
    if (moduleOf(file) === null || !file.endsWith("/index.ts")) continue;
    const source = readFileSync(resolve(repoRoot, file), "utf8");
    const lines = source.split("\n");
    lines.forEach((text, index) => {
      if (/^\s*export\s+(type\s+)?\*/.test(text)) {
        out.push({
          rule: "index-named-exports-only",
          file,
          line: index + 1,
          message:
            "Modul-index.ts darf kein `export *` verwenden — das laundert das Domainmodell ueber die Modulgrenze (EYT-46 AK 5).",
        });
      }
    });
  }
  return out;
}

/**
 * Architekturgrenzen, automatisiert (EYT-46, ADR-001 Z. 72-78).
 *
 * Läuft im Pflichtjob `unit-tests` (`pnpm test` -> `turbo run test`).
 *
 * Der eigentliche Wert steckt nicht in `violations === []`, sondern in den
 * Nicht-Leerlauf-Zusicherungen davor: eine Regel, die null Dateien sieht, meldet
 * ebenfalls null Verstösse. Genau so wird aus einem Sicherheitsnetz ein grüner
 * Haken ohne Inhalt. Deshalb ist der Umfang **registergetrieben**
 * (`SCAFFOLDED_MODULES`) statt glob-getrieben: ein Modul steht dort, weil ein
 * Ticket seinen Code geschrieben hat, und der Test verlangt daraufhin echte
 * Dateien — er belohnt nicht das Anlegen leerer Dateien, um einen Zähler zu heben.
 */
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";

import { describe, expect, it } from "vitest";

import { SCAFFOLDED_MODULES } from "../src/modules/module-catalogue";
import { evaluate, findStarReExports, moduleOf, RULES } from "./architecture/rules";
import { collectSourceFiles, extractImports, findRepoRoot } from "./architecture/scan";

const repoRoot = findRepoRoot(import.meta.dirname);

const files = [
  ...collectSourceFiles(repoRoot, "apps"),
  ...collectSourceFiles(repoRoot, "packages"),
];
const refs = extractImports(repoRoot, files);
const { violations, scopeCounts } = evaluate(refs);
const starReExports = findStarReExports(repoRoot, files);

describe("Architekturgrenzen", () => {
  it("hat ueberhaupt Quelltext gescannt", () => {
    // Untergrenze bewusst niedrig, aber weit ueber null: sie faengt einen
    // kaputten Walker oder ein falsches Arbeitsverzeichnis ab, nicht das
    // normale Wachsen des Repos.
    expect(files.length).toBeGreaterThan(30);
    expect(refs.length).toBeGreaterThan(30);
  });

  it("loest jeden relativen Import auf", () => {
    // Ein nicht aufgeloester relativer Import wuerde jede pfadbasierte Regel
    // stillschweigend ueberspringen — der gefaehrlichste Fehlerzustand des
    // Scanners, weil er wie ein sauberer Lauf aussieht.
    const unresolved = refs
      .filter((ref) => ref.specifier.startsWith(".") && ref.resolved === null)
      .map((ref) => `${ref.from}:${ref.line} -> ${ref.specifier}`);
    expect(unresolved).toEqual([]);
  });

  it.each(RULES.map((rule) => rule.id))("Regel %s ueberwacht mindestens eine Datei", (ruleId) => {
    expect(scopeCounts.get(ruleId)?.size ?? 0).toBeGreaterThan(0);
  });

  it.each([...SCAFFOLDED_MODULES])("Modul %s besitzt echten Inhalt und eine oeffentliche API", (slug) => {
    const base = `apps/api/src/modules/${slug}`;
    expect(existsSync(resolve(repoRoot, `${base}/index.ts`))).toBe(true);
    for (const layer of ["domain", "application"]) {
      const inLayer = files.filter((file) => file.startsWith(`${base}/${layer}/`));
      expect(inLayer.length, `${base}/${layer}/ ist leer — leere Schichten sind keine Grenzen`).toBeGreaterThan(0);
    }
  });

  it("verwendet keine tsconfig-Pfadaliase", () => {
    // Ein Alias wie "@/*" wuerde relative Regeln aushebeln: der Spezifizierer
    // saehe aus wie ein Paketname und liefe an jeder pfadbasierten Pruefung
    // vorbei. Die Regeln setzen die Abwesenheit voraus — also wird sie geprueft,
    // nicht kommentiert.
    const withPaths = files
      .filter((file) => file.endsWith("tsconfig.json") || file.endsWith("tsconfig.build.json"))
      .filter((file) => /"paths"\s*:/.test(readFileSync(resolve(repoRoot, file), "utf8")));
    expect(withPaths).toEqual([]);
  });

  it("bleibt an die Wurzel-Skripte gebunden", () => {
    // Der Test wirkt nur, solange `pnpm test` ihn ueberhaupt startet. Ein
    // spaeterer Aufraeum-Commit am Wurzel-Skript wuerde ihn sonst lautlos
    // entfernen, waehrend alle neun Pflichtchecks gruen bleiben.
    const rootPkg: unknown = JSON.parse(readFileSync(resolve(repoRoot, "package.json"), "utf8"));
    const scripts = (rootPkg as { scripts?: Record<string, string> }).scripts ?? {};
    expect(scripts["test"]).toContain("turbo run test");
  });

  it("haelt Modul-index.ts frei von Stern-Re-Exporten", () => {
    expect(starReExports.map((v) => `${v.file}:${v.line}`)).toEqual([]);
  });

  it("meldet keine Grenzverletzung", () => {
    const rendered = violations.map((v) => `${v.file}:${v.line} [${v.rule}] ${v.message}`);
    // eslint-disable-next-line no-console -- greppbare Zeile, wie beim Tenant-Gate.
    console.log(
      `[architecture] files=${files.length} imports=${refs.length} modules=${SCAFFOLDED_MODULES.length} rules=${RULES.length} violations=${rendered.length}`,
    );
    expect(rendered).toEqual([]);
  });

  it("ordnet jede Moduldatei einem bekannten Modul zu", () => {
    const orphans = files
      .filter((file) => file.startsWith("apps/api/src/modules/") && file.includes("/"))
      .filter((file) => moduleOf(file) === null && !file.endsWith("module-catalogue.ts"));
    expect(orphans).toEqual([]);
  });
});

/**
 * Rot-Fall-Beweis für den Architekturtest (EYT-46).
 *
 * Ein Wächter, der nie rot war, ist kein Wächter. Diese Suite baut einen
 * synthetischen Repo-Baum in einem temporären Verzeichnis, lässt exakt dieselbe
 * Pipeline darüber laufen (`collectSourceFiles` → `extractImports` → `evaluate`)
 * und verlangt, dass jede Regel dort anschlägt.
 *
 * Bewusst NICHT im echten Baum: eine Fixture-Datei unter `apps/api/src/` würde
 * mit `architecture.test.ts` um dieselben Dateien rennen und zusätzlich den
 * `typecheck`-Job brechen.
 *
 * Die Gegenbeispiele sind nicht ausgedacht: `http`, `pg-pool`,
 * `kysely/dist/esm/index.js`, `rxjs` und `typeorm` passieren jede naheliegende
 * Blockliste (`^node:(http|…)$`, `^pg$`, `^kysely$`) und sind der Grund, warum
 * `domain-allowlist` als Allowlist formuliert ist.
 */
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { evaluate, findStarReExports } from "./architecture/rules";
import { collectSourceFiles, extractImports } from "./architecture/scan";

let root: string;

function write(relative: string, contents: string): void {
  const abs = join(root, relative);
  mkdirSync(dirname(abs), { recursive: true });
  writeFileSync(abs, contents, "utf8");
}

function violationsFor(): ReturnType<typeof evaluate> {
  const files = [...collectSourceFiles(root, "apps"), ...collectSourceFiles(root, "packages")];
  return evaluate(extractImports(root, files));
}

function rulesTriggered(): Set<string> {
  return new Set(violationsFor().violations.map((v) => v.rule));
}

beforeAll(() => {
  root = mkdtempSync(join(tmpdir(), "eyt-arch-"));
  writeFileSync(join(root, "pnpm-workspace.yaml"), 'packages:\n  - "apps/*"\n', "utf8");

  // Zielmodul, damit relative Importe aufloesbar sind.
  write("apps/api/src/modules/workforce/index.ts", "export const marker = 1;\n");
  write("apps/api/src/modules/workforce/domain/employee.ts", "export const employee = 1;\n");
  write("apps/api/src/modules/workforce/application/port.ts", "export const port = 1;\n");
  write("apps/api/src/modules/workforce/infrastructure/repo.ts", "export const repo = 1;\n");
});

afterAll(() => {
  rmSync(root, { recursive: true, force: true });
});

describe("Rot-Fall", () => {
  it("faengt Framework- und Infrastrukturimporte im Domaincode", () => {
    write(
      "apps/api/src/modules/planning/domain/bad.ts",
      [
        'import http from "http";',
        'import { Pool } from "pg-pool";',
        'import type { Kysely } from "kysely/dist/esm/index.js";',
        'import { firstValueFrom } from "rxjs";',
        'import { Entity } from "typeorm";',
        'import { Injectable } from "@nestjs/common";',
        "export const bad = [http, Pool, firstValueFrom, Entity, Injectable] as const;",
        "export type Db = Kysely<unknown>;",
      ].join("\n") + "\n",
    );

    const found = violationsFor().violations.filter((v) => v.rule === "domain-allowlist");
    const specifiers = found.map((v) => v.message);
    for (const needle of ["http", "pg-pool", "kysely/dist/esm/index.js", "rxjs", "typeorm", "@nestjs/common"]) {
      expect(specifiers.some((m) => m.includes(`"${needle}"`)), `${needle} nicht erkannt`).toBe(true);
    }
    rmSync(join(root, "apps/api/src/modules/planning"), { recursive: true, force: true });
  });

  it("faengt eine /// <reference types> im Domaincode", () => {
    write(
      "apps/api/src/modules/planning/domain/ambient.ts",
      '/// <reference types="node" />\nexport const ambient = 1;\n',
    );
    expect(rulesTriggered().has("domain-allowlist")).toBe(true);
    rmSync(join(root, "apps/api/src/modules/planning"), { recursive: true, force: true });
  });

  it("faengt einen Querimport an der oeffentlichen Modul-API vorbei", () => {
    write(
      "apps/api/src/modules/planning/application/bypass.ts",
      'import { employee } from "../../workforce/domain/employee";\nexport const bypass = employee;\n',
    );
    expect(rulesTriggered().has("module-public-api-only")).toBe(true);
    rmSync(join(root, "apps/api/src/modules/planning"), { recursive: true, force: true });
  });

  it("faengt den Griff der Kompositionswurzel in ein Modul-Innenleben", () => {
    // Der wahrscheinlichste reale Verstoss in einer NestJS-Anwendung — und der
    // Grund, warum der Geltungsbereich ganz apps/api/src/** ist.
    write(
      "apps/api/src/app.module.ts",
      'import { repo } from "./modules/workforce/infrastructure/repo";\nexport const app = repo;\n',
    );
    expect(rulesTriggered().has("module-public-api-only")).toBe(true);
    rmSync(join(root, "apps/api/src/app.module.ts"), { force: true });
  });

  it("faengt eine verkehrte Schichtrichtung", () => {
    write(
      "apps/api/src/modules/workforce/application/wrong-direction.ts",
      'import { repo } from "../infrastructure/repo";\nexport const wrong = repo;\n',
    );
    expect(rulesTriggered().has("layer-direction")).toBe(true);
    rmSync(join(root, "apps/api/src/modules/workforce/application/wrong-direction.ts"), { force: true });
  });

  it("faengt einen App-zu-App-Import", () => {
    write("apps/web/lib/leak.ts", 'import { marker } from "../../api/src/modules/workforce/index";\nexport const leak = marker;\n');
    expect(rulesTriggered().has("no-app-to-app")).toBe(true);
    rmSync(join(root, "apps/web"), { recursive: true, force: true });
  });

  it("faengt ein unspezifisches Sammelpaket, auch unter anderem Namen", () => {
    write("apps/api/src/uses-grab-bag.ts", 'import { x } from "@easytree/common";\nexport const y = x;\n');
    expect(rulesTriggered().has("no-generic-shared-package")).toBe(true);
    rmSync(join(root, "apps/api/src/uses-grab-bag.ts"), { force: true });
  });

  it("faengt Prototype-Fixtures im Produktionscode", () => {
    write("apps/api/src/uses-fixtures.ts", 'import { f } from "@easytree/prototype-fixtures";\nexport const g = f;\n');
    expect(rulesTriggered().has("no-fixtures-in-production-code")).toBe(true);
    rmSync(join(root, "apps/api/src/uses-fixtures.ts"), { force: true });
  });

  it("faengt ein `export *` in einer Modul-index.ts", () => {
    write("apps/api/src/modules/workforce/index.ts", 'export * from "./domain/employee";\n');
    const files = [...collectSourceFiles(root, "apps"), ...collectSourceFiles(root, "packages")];
    expect(findStarReExports(root, files).length).toBeGreaterThan(0);
    write("apps/api/src/modules/workforce/index.ts", "export const marker = 1;\n");
  });

  it("ist am sauberen Baum gruen — der Rot-Fall kommt von den Verstoessen, nicht vom Aufbau", () => {
    expect(violationsFor().violations).toEqual([]);
  });
});

