// TEMPORARY ATTACK PROBE — delete after review.
import { describe, expect, it } from "vitest";

import {
  createTimeInterval,
  durationMinutes,
  hasAnyOverlap,
  overlaps,
  type TimeInterval,
} from "../src/time-interval.js";

function valid(startIso: string, endIso: string): TimeInterval {
  const r = createTimeInterval(new Date(startIso), new Date(endIso));
  if (!r.ok) throw new Error(r.error);
  return r.interval;
}

describe("ATTACK", () => {
  it("A3: spread with no cast yields an inverted interval and NEGATIVE duration", () => {
    const good = valid("2026-08-03T08:00:00Z", "2026-08-03T16:00:00Z");
    const inverted: TimeInterval = { ...good, startUtc: good.endUtc, endUtc: good.startUtc };
    expect(durationMinutes(inverted)).toBe(-480);
    expect(overlaps(inverted, good)).toBe(false);
  });

  it("A4: Object.assign with no cast, start === end -> duration 0, overlaps false", () => {
    const good = valid("2026-08-03T08:00:00Z", "2026-08-03T16:00:00Z");
    const point: TimeInterval = Object.assign({}, good, { endUtc: good.startUtc });
    expect(durationMinutes(point)).toBe(0);
    // Zero-length interval overlaps NOTHING under half-open comparison:
    expect(overlaps(point, good)).toBe(false);
    expect(hasAnyOverlap([point, good])).toBe(false);
