import { describe, expect, it } from "vitest";

import {
  createTimeInterval,
  durationMinutes,
  hasAnyOverlap,
  overlaps,
  type TimeInterval,
} from "../src/time-interval.js";

function valid(a: string, b: string): TimeInterval {
  const r = createTimeInterval(new Date(a), new Date(b));
  if (!r.ok) throw new Error(r.error);
  return r.interval;
}

describe("RV2 semantics probe", () => {
  // --- B1: spread, NO cast, NO ts-ignore ---
  it("B1 spread without cast yields negative duration", () => {
    const good = valid("2026-08-03T08:00:00Z", "2026-08-03T16:00:00Z");
    const inverted: TimeInterval = { ...good, startUtc: good.endUtc, endUtc: good.startUtc };
    expect(durationMinutes(inverted)).toBe(-480);
    expect(overlaps(inverted, good)).toBe(false);
  });

  // --- B2: Object.assign, NO cast -> zero-length ---
  it("B2 Object.assign without cast yields zero-length interval", () => {
    const good = valid("2026-08-03T08:00:00Z", "2026-08-03T16:00:00Z");
    const point: TimeInterval = Object.assign({}, good, { endUtc: good.startUtc });
    expect(durationMinutes(point)).toBe(0);
    expect(overlaps(point, good)).toBe(false);
    expect(hasAnyOverlap([point, good])).toBe(false);
  });

  // --- B3: mutate Date inside a validated interval, NO cast ---
  it("B3 date mutation collapses a validated interval", () => {
    const good = valid("2026-08-03T08:00:00Z", "2026-08-03T16:00:00Z");
    const other = valid("2026-08-03T09:00:00Z", "2026-08-03T10:00:00Z");
    expect(overlaps(good, other)).toBe(true);
    good.endUtc.setTime(good.startUtc.getTime());
    expect(durationMinutes(good)).toBe(0);
    expect(overlaps(good, other)).toBe(false);
  });

  // --- B4: exhaustive search for a hasAnyOverlap counterexample on VALID intervals ---
  it("B4 no counterexample for neighbour-only hasAnyOverlap over valid intervals", () => {
    const base = Date.UTC(2026, 7, 3, 0, 0, 0);
    const pts = [0, 1, 2, 3, 4, 5];
    const all: TimeInterval[] = [];
    for (const s of pts) {
      for (const e of pts) {
        if (e <= s) continue;
        all.push(valid(new Date(base + s * 3_600_000).toISOString(), new Date(base + e * 3_600_000).toISOString()));
      }
    }
    const bruteForce = (xs: readonly TimeInterval[]): boolean => {
      for (let i = 0; i < xs.length; i += 1)
        for (let j = i + 1; j < xs.length; j += 1) {
          const a = xs[i];
          const b = xs[j];
          if (a && b && overlaps(a, b)) return true;
        }
      return false;
    };
    let triples = 0;
    let mismatches = 0;
    for (let i = 0; i < all.length; i += 1)
      for (let j = 0; j < all.length; j += 1)
        for (let k = 0; k < all.length; k += 1) {
          const set = [all[i]!, all[j]!, all[k]!];
          triples += 1;
          if (hasAnyOverlap(set) !== bruteForce(set)) mismatches += 1;
        }
    expect(triples).toBeGreaterThan(1000);
    expect(mismatches).toBe(0);
  });

  // --- B5: does a MUTATED (zero-length) interval break hasAnyOverlap completeness? ---
  it("B5 zero-length interval nested inside another is invisible to hasAnyOverlap", () => {
    const long = valid("2026-08-03T06:00:00Z", "2026-08-03T20:00:00Z");
    const point: TimeInterval = Object.assign({}, long, {
      startUtc: new Date("2026-08-03T10:00:00Z"),
      endUtc: new Date("2026-08-03T10:00:00Z"),
    });
    expect(overlaps(long, point)).toBe(false);
    expect(hasAnyOverlap([long, point])).toBe(false);
  });
});

