// TEMPORARY ATTACK PROBE — delete after review.
import { createTimeInterval, unsafeIdentifier } from "@easytree/domain";
import type { AssignmentId, EmployeeId, OrgId, TimeInterval, WorksiteId } from "@easytree/domain";
import { describe, expect, it } from "vitest";

import { conflictsWithExisting } from "../src/modules/planning";
import type { AssignmentDraft } from "../src/modules/planning";

const ORG = unsafeIdentifier<OrgId>("00000000-0000-0000-0000-0000000000a1");
const ANNA = unsafeIdentifier<EmployeeId>("00000000-0000-0000-0000-00000000aaa1");
const SITE = unsafeIdentifier<WorksiteId>("00000000-0000-0000-0000-0000000011c1");

function at(startIso: string, endIso: string): TimeInterval {
  const r = createTimeInterval(new Date(startIso), new Date(endIso));
  if (!r.ok) throw new Error(r.error);
  return r.interval;
}

function draft(id: string, interval: TimeInterval): AssignmentDraft {
  return {
    id: unsafeIdentifier<AssignmentId>(id),
    orgId: ORG,
    employeeId: ANNA,
    worksiteId: SITE,
    interval,
  };
}

/**
 * Plausible future production helper: "move this assignment N minutes later".
 * No `as`, no `any`, no ts-ignore. Typechecks against the BUILT dist .d.ts.
 */
function shiftBy(interval: TimeInterval, minutes: number): TimeInterval {
  return {
    ...interval,
    startUtc: new Date(interval.startUtc.getTime() + minutes * 60_000),
    // typo/bug: minus instead of plus — the type system does not care
    endUtc: new Date(interval.endUtc.getTime() - minutes * 60_000),
  };
}

describe("ATTACK cross-package", () => {
  it("spread across the package boundary produces an inverted TimeInterval", () => {
    const broken = shiftBy(at("2026-08-03T08:00:00Z", "2026-08-03T09:00:00Z"), 120);
    expect(broken.startUtc.getTime()).toBeGreaterThan(broken.endUtc.getTime());
  });

  it("the inverted interval silently passes the publish-blocking conflict check", () => {
    const existing = draft("a1", at("2026-08-03T08:00:00Z", "2026-08-03T18:00:00Z"));
    const broken = draft("a2", shiftBy(at("2026-08-03T08:00:00Z", "2026-08-03T09:00:00Z"), 120));
    // Genuinely inside the existing shift, but reported as conflict-free:
    expect(conflictsWithExisting(broken, [existing])).toBe(false);
  });

  it("a zero-length interval is invisible to every overlap check", () => {
    const good = at("2026-08-03T08:00:00Z", "2026-08-03T18:00:00Z");
    const point: TimeInterval = { ...good, endUtc: good.startUtc };
    const existing = draft("a1", good);
    expect(conflictsWithExisting(draft("a2", point), [existing])).toBe(false);
  });

  it("post-construction mutation of a validated interval", () => {
    const good = at("2026-08-03T08:00:00Z", "2026-08-03T18:00:00Z");
    const existing = draft("a1", good);
    const clash = draft("a2", at("2026-08-03T10:00:00Z", "2026-08-03T11:00:00Z"));
    expect(conflictsWithExisting(clash, [existing])).toBe(true);
    good.endUtc.setUTCFullYear(1999); // readonly property, mutable Date
    expect(conflictsWithExisting(clash, [existing])).toBe(false);
  });
});

