 *  and cannot drift. Half-open [startUtc, endUtc) — same convention as the domain
 *  (time-interval.ts:53-58, INTEGRATION_ARCHITECTURE.md:107). */
export interface TimeIntervalDto {
  readonly startUtc: InstantUtc;
  readonly endUtc: InstantUtc;   // exclusive
}

