                                     // compute it differently, which is the original FIND-004 bug.
}

export interface CreateAssignmentDraftResponseDto {
  readonly draft: AssignmentDraftDto;
  readonly conflicts: readonly PlanningConflictDto[];  // mirrors PlanningCommands
