  "EMPLOYEE_WEEKLY_CAPACITY",
  "EMPLOYEE_INACTIVE",
  "WORKSITE_NOT_PUBLISHABLE",
] as const;
export type ConflictCodeDto = (typeof CONFLICT_CODE_DTOS)[number];

export interface PlanningConflictDto {
  readonly code: ConflictCodeDto;
