  readonly weekKey?: WeekKey;
}

export interface ValidateDraftResponseDto {
  readonly conflicts: readonly PlanningConflictDto[];
  /** Derived, but sent explicitly so the client never re-implements the rule:
   *  `conflicts.every(c => !c.blocking)`. INTEGRATION_ARCHITECTURE.md:110 — client conflict
   *  logic may give UX feedback but is never the authority. */
  readonly publishable: boolean;
}

