```

None of the 12 named payload types exists anywhere in the repo (verified: `packages/domain/src/index.ts:14-72` exports none of them; `apps/api/src/modules/planning/index.ts:9-13` exports none of them). The audit block is a **shape**, not a compiling contract. Every payload type below is therefore new; the deviations list records which ones changed *name or signature* rather than merely being filled in.

## B. Package placement

`packages/contracts` (`@easytree/contracts`), per ADR-002 §5 (`docs/architecture/ADR-002-integration-canonical-repo.md:93-106`), which explicitly supersedes TASK-012's `packages/api-client` (`docs/plans/2026-07-23-boilerplate-architecture.md:281-291` names `packages/api-client`; ADR-002 line 105: "`packages/api-client` entfällt zugunsten von `packages/contracts`").

**Which architecture-guard rule applies to `packages/contracts`:**

| Rule (`apps/api/test/architecture/rules.ts`) | Applies? | Consequence |
|---|---|---|
| `no-generic-shared-package` (`rules.ts:183-202`) | **Yes — this is the one that polices the new package.** `inScope: () => true` (`rules.ts:186`). It matches `/^@easytree\/([a-z-]+)$/` and rejects the names in `GENERIC_PACKAGE_NAMES` = shared, common, utils, util, misc, core, helpers, lib (`rules.ts:76-85`). `contracts` is not in that list, and the *second* half of the check (`rules.ts:193-199`) also passes because `packages/contracts/` is not a generic directory name. **Passes.** |
| `no-app-to-app` (`rules.ts:158-182`) | Yes, `inScope` covers `packages/` (`rules.ts:161`). Forbids `@easytree/api` / `@easytree/web` specifiers and any resolved path into `apps/` (`rules.ts:173-175`). **This is the decisive placement constraint** — see deviation D-8 and the contract-test section. |
| `domain-allowlist` (`rules.ts:92-117`) | **No.** `isDomainFile` is `file.startsWith("packages/domain/src/") \|\| layerOf(file) === "domain"` (`rules.ts:87-89`), and `layerOf` returns non-null only under `apps/api/src/modules/<slug>/` (`rules.ts:60-66`). So `packages/contracts/src/**` is unconstrained by the domain allowlist and may depend on a validation library. |
| `no-fixtures-in-production-code` (`rules.ts:203-212`) | **Yes, and it bites.** In-scope = any file *not* under `test/`, `e2e/`, `__tests__/` (`rules.ts:206`). So `packages/contracts/src/mock/**` may **not** import `@easytree/prototype-fixtures`. See D-9. |
| `module-public-api-only` (`rules.ts:118-132`), `layer-direction` (`rules.ts:133-157`) | No — both scoped to `apps/api/src/`. |
| `index-named-exports-only` (`rules.ts:243-262`) | No — `findStarReExports` skips files where `moduleOf(file) === null`. **However**, `packages/domain/src/index.ts:14-72` already uses named-only re-exports as house style; `packages/contracts/src/index.ts` should do the same voluntarily. |

The package is scanned regardless: `architecture.test.ts:35-37` collects `apps` **and** `packages`.

## C. Shared state types (`packages/contracts/src/gateway-state.ts`)

```ts
import type { PlanVersionId } from "@easytree/domain";
import type { PlanningConflictView } from "./planning/conflict-view.js";

export const GATEWAY_ERROR_KINDS = [
  "OFFLINE",        // Request hat den Server nie erreicht
  "TIMEOUT",
  "UNAUTHENTICATED",
  "FORBIDDEN",
  "NOT_FOUND",
  "VALIDATION",     // Server hat das Kommando abgelehnt (RFC-7807 400/422)
  "CONFLICT",       // blockierender Domainkonflikt
  "STALE_VERSION",  // optimistische Nebenlaeufigkeit
  "RATE_LIMITED",
  "SERVER",         // 5xx
  "CONTRACT",       // Antwort passte nicht zum Vertrag -> fail closed
] as const;
export type GatewayErrorKind = (typeof GATEWAY_ERROR_KINDS)[number];

interface GatewayProblemBase {
  readonly status: number | null;      // null = kein HTTP-Roundtrip
  readonly title: string;              // aus ProblemDocument.title
  readonly detail: string;             // aus ProblemDocument.detail
  readonly correlationId: string | null;
  readonly retryable: boolean;
}

export interface GatewayProblem extends GatewayProblemBase {
  readonly kind: Exclude<GatewayErrorKind, "CONFLICT" | "STALE_VERSION">;
}

export interface GatewayConflictProblem extends GatewayProblemBase {
  readonly kind: "CONFLICT";
  readonly retryable: false;
  readonly conflicts: readonly PlanningConflictView[];
}

export interface GatewayStaleVersionProblem extends GatewayProblemBase {
  readonly kind: "STALE_VERSION";
  readonly retryable: false;
  readonly sentPlanVersionId: PlanVersionId | null;
  readonly currentPlanVersionId: PlanVersionId;
}

export type GatewayError =
  | GatewayProblem
  | GatewayConflictProblem
  | GatewayStaleVersionProblem;

export type GatewayResult<T> =
  | { readonly ok: true; readonly data: T }
  | { readonly ok: false; readonly error: GatewayError };

export const EMPTY_REASONS = [
  "NO_PLAN_PUBLISHED",
  "NO_ASSIGNMENTS_IN_WEEK",
  "NO_ACTIVE_TIME_ENTRY",
] as const;
export type EmptyReason = (typeof EMPTY_REASONS)[number];

export type Loaded<T> =
  | { readonly kind: "present"; readonly value: T }
  | { readonly kind: "empty"; readonly reason: EmptyReason };

declare const idempotencyBrand: unique symbol;
export type IdempotencyKey = string & { readonly [idempotencyBrand]: "IdempotencyKey" };
export function newIdempotencyKey(): IdempotencyKey;   // crypto.randomUUID(), Node 22 + Browser, offline
```

The four `GatewayProblemBase` fields are a 1:1 mirror of the API's `ProblemDocument` (`apps/api/src/common/http-exception.filter.ts:15-21`: `type`, `title`, `status`, `detail`, `correlationId`). The HTTP adapter parses exactly that document; nothing has to be invented server-side.

## D. Final `PlanningGateway`

```ts
// packages/contracts/src/planning/planning.gateway.ts
import type {
  AssignmentId, EmployeeId, IanaTimeZone, OrgId,
  PlanningWeek, PlanVersionId, TimeInterval, WorksiteId,
} from "@easytree/domain";
import type { ConflictCode } from "@easytree/domain";          // s. D-7
import type { GatewayResult, IdempotencyKey, Loaded } from "../gateway-state.js";

export interface PlanningConflictView {
  readonly code: ConflictCode;
  readonly blocking: boolean;
  readonly employeeId: EmployeeId | null;
  readonly assignmentIds: readonly AssignmentId[];
}

export interface AssignmentView {
  readonly id: AssignmentId;
  readonly employeeId: EmployeeId;
  readonly employeeDisplayName: string;
  readonly worksiteId: WorksiteId;
  readonly worksiteName: string;
  /** Geprueftes Intervall, nie ein loses ISO-Paar (FIND-004). */
  readonly interval: TimeInterval;
}

interface PlannedWeekBase {
  readonly orgId: OrgId;
  readonly week: PlanningWeek;
  /** `2026-W32` — identisch zu planningWeekKey(week). */
  readonly weekKey: string;
  /** Zone, in der der Server aggregiert hat. Der Client waehlt sie NICHT. */
  readonly timeZone: IanaTimeZone;
  readonly assignments: readonly AssignmentView[];
  readonly conflicts: readonly PlanningConflictView[];
}

export type PlannedWeek =
  | (PlannedWeekBase & { readonly status: "DRAFT"; readonly publishedVersionId: null })
  | (PlannedWeekBase & {
      readonly status: "PUBLISHED";
      readonly publishedVersionId: PlanVersionId;
      readonly hasUnpublishedChanges: boolean;
    });

export interface PlanningWeekQuery {
  readonly orgId: OrgId;
  readonly week: PlanningWeek;
}

export interface ValidateDraftCommand {
  readonly orgId: OrgId;
  readonly employeeId: EmployeeId;
  readonly worksiteId: WorksiteId;
  readonly interval: TimeInterval;
  /** Gesetzt = bestehende Zuweisung wird bearbeitet; null = Neuanlage. */
  readonly replacesAssignmentId: AssignmentId | null;
}

export interface DraftValidation {
  readonly conflicts: readonly PlanningConflictView[];
  readonly blocking: boolean;
}

export interface CreateAssignmentDraftCommand {
  readonly orgId: OrgId;
  readonly employeeId: EmployeeId;
  readonly worksiteId: WorksiteId;
  readonly interval: TimeInterval;
  readonly idempotencyKey: IdempotencyKey;
}

export interface PublishPlanCommand {
  readonly orgId: OrgId;
  readonly week: PlanningWeek;
  /** Version, auf der der Planer gearbeitet hat; null = noch nie veroeffentlicht. */
  readonly expectedPlanVersionId: PlanVersionId | null;
  readonly idempotencyKey: IdempotencyKey;
}

