revoke all on table public.outbox_events from anon;
-- BEWUSST kein update/delete-Grant: Claiming/Markieren ist Aufgabe des Workers
-- (TASK-013) mit eigener Rolle/eigener Migration. Gleiches Muster wie memberships
-- (0002_tenancy.sql:129-130, 181-183): fail closed, Grant kommt mit dem Code.
grant select, insert on table public.outbox_events to authenticated;

alter table public.outbox_events enable row level security;
alter table public.outbox_events force row level security;

create policy outbox_events_select_in_org on public.outbox_events
  for select to authenticated
  using (org_id in (select app.user_org_ids()));

create policy outbox_events_insert_in_org on public.outbox_events
  for insert to authenticated
