  i % 4 === 3 ? { userId: USER_C, orgId: ORG_ALPHA }      // inaktiv -> sieht nichts
  : i % 4 === 2 ? { userId: USER_B, orgId: ORG_BETA }
  : { userId: USER_A, orgId: ORG_ALPHA });

const observed = await Promise.all(
  principals.map((p, i) =>
    uow.runInTenant(p, async (tx) => {
      // Interleaving ERZWINGEN: ohne das koennen die Transaktionen
      // sequenziell durchlaufen und der Test waere leer.
      await tx.executeRaw(sql`select pg_sleep(${0.02 + (i % 5) * 0.01})`);
      const probe = await tx.executeRaw(sql<{ uid: string | null; role: string; pid: number }>`
        select (select app.current_user_id())::text as uid,
               current_user::text                    as role,
               pg_backend_pid()                      as pid
      `);
      const rows = await tx.from("items").select(["id", "org_id"]).execute();
