/**
 * Leseport der Planung (EYT-50).
 *
 * Bewusst KEINE Transporttypen: was hier herauskommt, ist der Stand der
 * Datenbank, nicht die Antwortform. Die Abbildung auf `PlanningWindow` aus
 * `@easytree/contracts` gehoert in die interface-Schicht — sonst waere der
 * Vertrag ueber die Anwendungsschicht bis ins Repository durchgereicht, und
 * eine Vertragsaenderung zoege eine Repositoryaenderung nach sich.
 *
 * Die Organisation steht in KEINER Signatur. Sie kommt ausschliesslich aus dem
 * gesetzten Datenbankkontext (`app.user_org_ids()` ueber RLS). Ein Parameter
 * `orgId` waere die Einladung, ihn aus der URL zu befuellen.
 */

/** Eine Zuweisung, so wie sie in der Datenbank steht. */
export interface AssignmentRow {
  readonly id: string;
  readonly employeeId: string;
  readonly worksiteId: string;
  readonly startsAtUtc: Date;
  readonly endsAtUtc: Date;
}

export interface PlanningWindowRow {
  readonly weekKey: string;
  /** IANA-Zone der Organisation aus `organizations.time_zone` (Migration 0004). */
  readonly timeZone: string;
  /**
   * Der bearbeitbare Stand: Zuweisungen des Entwurfs, sonst die der zuletzt
   * veroeffentlichten Version, sonst leer.
   * Begruendung in docs/decisions/2026-07-27-eyt-50-lesesemantik-planungsfenster.md.
   */
  readonly assignments: readonly AssignmentRow[];
  /** Zuletzt veroeffentlichte Version derselben Woche, oder `null`. */
  readonly publishedVersionId: string | null;
}

/** Warum eine Leseanfrage nicht beantwortbar ist. */
export type PlanningQueryProblem =
  /** Angemeldet, aber ohne aktive Mitgliedschaft. */
  | "NO_ORGANISATION"
  /**
   * Mehrere aktive Mitgliedschaften. KEINE stille Auswahl: eine davon zu
   * nehmen waere eine erfundene Mandantenentscheidung, die niemandem auffiele,
   * weil das Ergebnis plausibel aussieht. Der Organisationswechsler gehoert zu
   * EYT-14.
   */
  | "AMBIGUOUS_ORGANISATION";

export type PlanningWindowResult =
  | { readonly ok: true; readonly window: PlanningWindowRow }
  | { readonly ok: false; readonly problem: PlanningQueryProblem };

export interface PlanningQueries {
  /** Liest das Fenster einer ISO-Woche im Mandanten des gesetzten Kontexts. */
  planningWindow(weekKey: string): Promise<PlanningWindowResult>;
}

/** DI-Token. Tests ersetzen ihn, genau wie `DATABASE_PING`. */
export const PLANNING_QUERIES = "PLANNING_QUERIES";

/**
 * Leserepository des Planungsfensters (EYT-50).
 *
 * ## Kein Treiber, nur `TenantQuery`
 *
 * Diese Datei importiert `pg` NICHT. `api-dependency-allowlist` (EYT-45)
 * erlaubt den Treiber ausschliesslich unter `apps/api/src/platform/` — und das
 * ist keine Formalie: ein Treiber im Fachmodul heisst, dass irgendwann jemand
 * eine Query an Transaktionsgrenze, Rollenwechsel und RLS vorbei absetzt.
 *
 * ## Keine Organisations-Id in einer Query
 *
 * Kein SQL hier nennt `org_id` in einer WHERE-Klausel. Die Mandantengrenze
 * kommt aus RLS, also aus `app.user_org_ids()` und damit aus dem verifizierten
 * Subjekt, das `PgTenantQueryRunner` transaktionslokal gesetzt hat. Eine
 * selbst gefilterte `org_id` waere eine zweite, schwaechere Grenze neben der
 * erzwungenen — und die schwaechere gewinnt immer dann, wenn jemand sie
 * vergisst.
 *
 * ## Keine Wochenberechnung
 *
 * `week_key` wird verglichen, nicht gerechnet. Die Umrechnung Woche -> UTC gibt
 * es im Repository nicht und soll es nicht geben (Entscheidungsnotiz
 * docs/decisions/2026-07-27-eyt-50-lesesemantik-planungsfenster.md, Punkt 1):
 * sie waere ein zweiter Ableitungspfad neben `packages/domain` und braeuchte
 * die Wanduhr->UTC-Richtung, die `no-local-time-construction` verbietet.
 */
import type {
  AssignmentRow,
  PlanningQueries,
  PlanningWindowResult,
} from "../application/planning-queries.port";
import type { TenantQuery, TenantQueryRunner } from "../../../platform/database/tenant-query-runner";

interface OrgRow {
  readonly id: string;
  readonly time_zone: string;
}

interface VersionRow {
  readonly id: string;
  readonly published_at: Date | null;
}

interface RawAssignmentRow {
  readonly id: string;
  readonly employee_id: string;
  readonly worksite_id: string;
  readonly starts_at_utc: Date;
  readonly ends_at_utc: Date;
}

export class PlanningWindowRepository implements PlanningQueries {
  constructor(
    private readonly runner: TenantQueryRunner,
    private readonly subjectUserId: string,
  ) {}

  async planningWindow(weekKey: string): Promise<PlanningWindowResult> {
    return this.runner.run({ userId: this.subjectUserId }, async (tx) => {
      // RLS liefert genau die Organisationen der aktiven Mitgliedschaften.
      // Kein Filter noetig — und keiner erlaubt.
      const orgs = await tx.query<OrgRow>("select id, time_zone from public.organizations");
      if (orgs.rows.length === 0) return { ok: false, problem: "NO_ORGANISATION" as const };
      if (orgs.rows.length > 1) {
        return { ok: false, problem: "AMBIGUOUS_ORGANISATION" as const };
      }
      const org = orgs.rows[0];
      if (org === undefined) return { ok: false, problem: "NO_ORGANISATION" as const };

      // Alle Versionen dieser Woche. Mehrere veroeffentlichte sind erlaubt
      // (der Unique-Index aus 0007 ist partiell und begrenzt nur Entwuerfe),
      // hoechstens ein Entwurf.
      const versions = await tx.query<VersionRow>(
        `select id, published_at
           from public.plan_versions
          where week_key = $1
          order by published_at asc nulls last`,
        [weekKey],
      );

      const draft = versions.rows.find((row) => row.published_at === null) ?? null;
      const published = versions.rows.filter((row) => row.published_at !== null);
      const latestPublished = published.length === 0 ? null : published[published.length - 1];

      // Der bearbeitbare Stand: Entwurf, sonst zuletzt Veroeffentlichtes,
      // sonst nichts (Entscheidungsnotiz, Punkt 2).
      const source = draft ?? latestPublished;

      const assignments =
        source === null || source === undefined
          ? []
          : await this.assignmentsOf(tx, source.id);

      return {
        ok: true as const,
        window: {
          weekKey,
          timeZone: org.time_zone,
          assignments,
          publishedVersionId: latestPublished?.id ?? null,
        },
      };
    });
  }

  private async assignmentsOf(tx: TenantQuery, planVersionId: string): Promise<AssignmentRow[]> {
    const rows = await tx.query<RawAssignmentRow>(
      `select id, employee_id, worksite_id, starts_at_utc, ends_at_utc
         from public.assignments
        where plan_version_id = $1
        order by starts_at_utc asc, id asc`,
      [planVersionId],
    );
    return rows.rows.map((row) => ({
      id: row.id,
      employeeId: row.employee_id,
      worksiteId: row.worksite_id,
      startsAtUtc: row.starts_at_utc,
      endsAtUtc: row.ends_at_utc,
    }));
  }
}

/**
 * HTTP-Naht der Planung (EYT-50).
 *
 * Die erste Fachroute des Projekts. Sie ist bewusst schmal: lesen, sonst
 * nichts.
 *
 * ## Reihenfolge der Pruefungen, und warum sie so ist
 *
 * 1. Subjekt. Ohne verifiziertes Subjekt endet die Anfrage mit 401, BEVOR
 *    irgendeine Query entsteht. Eine Query ohne Subjekt liefe mit leerem
 *    `app.user_org_ids()` — jede Policy griffe fail-closed, und das Ergebnis
 *    waere ein leeres Fenster statt einer Ablehnung. Ein leeres Fenster sieht
 *    aus wie "diese Woche ist nicht geplant"; genau diese Verwechslung soll
 *    hier nicht entstehen.
 * 2. Eingabe. `PlanningWindowQuerySchema` aus dem Vertrag, nicht eine eigene
 *    Pruefung. Ein zweiter Satz Regeln waere ein zweiter Ableitungspfad.
 * 3. Abfrage.
 * 4. Antwort gegen `PlanningWindowSchema`. Der Server prueft seine EIGENE
 *    Ausgabe, weil ein Vertragsbruch hier entsteht und nicht beim Client — und
 *    weil der Client ihn sonst als CONTRACT_VIOLATION meldet, ohne dass
 *    jemand die Ursache sieht.
 */
import { PlanningWindowQuerySchema, PlanningWindowSchema } from "@easytree/contracts";
import {
  BadRequestException,
  Controller,
  ForbiddenException,
  Get,
  Inject,
  InternalServerErrorException,
  Query,
  Req,
  UnauthorizedException,
} from "@nestjs/common";

import {
  TENANT_SUBJECT_RESOLVER,
  type TenantSubjectResolver,
} from "../../../../common/tenant-subject";
import {
  PLANNING_QUERIES_FACTORY,
  type PlanningQueriesFactory,
} from "../../application/planning-queries.factory";

@Controller("planung")
export class PlanningController {
  constructor(
    @Inject(TENANT_SUBJECT_RESOLVER)
    private readonly subjects: TenantSubjectResolver,
    @Inject(PLANNING_QUERIES_FACTORY)
    private readonly queriesFor: PlanningQueriesFactory,
  ) {}

  @Get("fenster")
  async planningWindow(
    @Req() request: unknown,
    @Query("weekKey") weekKey?: string,
  ): Promise<unknown> {
    const subject = this.subjects.resolve(request);
    if (subject === null) {
      // Kein Detail zur Ursache: ob ein Token fehlte, abgelaufen war oder
      // ungueltig ist, geht den Aufrufer nichts an.
      throw new UnauthorizedException("Kein verifiziertes Subjekt.");
    }

    const query = PlanningWindowQuerySchema.safeParse({ weekKey });
    if (!query.success) {
      throw new BadRequestException(
        "weekKey fehlt oder hat nicht das Format 2026-W32.",
      );
    }

    const result = await this.queriesFor(subject).planningWindow(query.data.weekKey);
    if (!result.ok) {
      if (result.problem === "NO_ORGANISATION") {
        throw new ForbiddenException("Keine aktive Mitgliedschaft in einer Organisation.");
      }
      // Mehrere Organisationen: ausdruecklich KEINE stille Auswahl. Der
      // Organisationswechsler ist eine Produktentscheidung (EYT-14).
      throw new ForbiddenException(
        "Mehrere aktive Organisationen. Die Auswahl ist noch nicht modelliert (EYT-14).",
      );
    }

    const body = {
      weekKey: result.window.weekKey,
      timeZone: result.window.timeZone,
      assignments: result.window.assignments.map((assignment) => ({
        id: assignment.id,
        employeeId: assignment.employeeId,
        worksiteId: assignment.worksiteId,
        interval: {
          startUtc: assignment.startsAtUtc.toISOString(),
          endUtc: assignment.endsAtUtc.toISOString(),
        },
      })),
      publishedVersionId: result.window.publishedVersionId,
    };

    const validated = PlanningWindowSchema.safeParse(body);
    if (!validated.success) {
      // Der Server hat etwas gebaut, das seinem eigenen Vertrag nicht
      // entspricht. Das ist ein Serverfehler, kein Aufruferfehler — und er
      // gehoert hierhin gemeldet, nicht als kaputte Antwort hinausgereicht.
      throw new InternalServerErrorException("Antwort entspricht nicht dem Vertrag.");
    }
    return validated.data;
  }
}

