      startUtc: "2026-08-03T06:00:00.000Z",
      endUtc: "2026-08-03T14:00:00.000Z",
    });
    expect(response.body.publishedVersionId).toBe("44444444-4444-4444-8444-444444444444");
  });

  it("antwortet bei fehlender Organisation mit 403", async () => {
