"use client";

/**
 * Read-only Planungsfenster (EYT-50).
 *
 * Bewusst schmal: die kleinste Ansicht, die den SERVERSTAND zeigt. Kein
 * Planner, keine Bearbeitung, keine Wochennavigation — das ist EYT-72.
 *
 * ## Vier Zustaende, alle sichtbar
 *
 * laden, leer, Fehler, Erfolg. Der Fehlerzustand ist der wichtigste: er zeigt
 * den Grund aus dem Port (`GatewayFailure`) an, statt eine leere Woche zu
 * rendern. Eine leere Woche und eine fehlgeschlagene Abfrage sehen sonst
 * identisch aus, und der Ausfall wuerde als "nichts geplant" gelesen.
 *
 * ## Kein Fallback
 *
 * Es gibt keinen Zweig, der bei einem Fehler Testdaten oder einen zuletzt
 * bekannten Stand aus dem Browser zeigt. EYT-50 AK10 verlangt ausdruecklich,
 * dass kein Mock- oder LocalStorage-Zustand operative Wahrheit ist — und ein
 * Fallback macht aus einem sichtbaren Ausfall eine plausible Anzeige.
 *
 * ## Warum die IDs sichtbar sind
 *
 * `data-assignment-id` und `data-published-version-id` stehen im Markup, weil
 * AK9 verlangt, dass Planer- und Mitarbeiteransicht DIESELBEN serverseitig
 * vergebenen Ids zeigen. Ohne sie liesse sich das nur ueber Text vergleichen,
 * und Text ist Darstellung.
 */
import type { GatewayFailure, PlanningWindow } from "@easytree/contracts";
import { Card } from "@easytree/ui";
import { useEffect, useState } from "react";

import { usePlanningGateway } from "../lib/planning-gateway-provider";

type ViewState =
  | { readonly kind: "laedt" }
  | { readonly kind: "fehler"; readonly failure: GatewayFailure }
  | { readonly kind: "geladen"; readonly window: PlanningWindow };

/** Deutscher Text je Portfehler. Bewusst vollstaendig — kein Standardzweig. */
const FAILURE_TEXT: Record<GatewayFailure, string> = {
  UNAVAILABLE: "Der Server ist nicht erreichbar.",
  CONTRACT_VIOLATION: "Die Antwort des Servers entspricht nicht dem Vertrag.",
  UNAUTHENTICATED: "Nicht angemeldet.",
  FORBIDDEN: "Keine Berechtigung fuer diese Organisation.",
  STALE_VERSION: "Der Stand ist veraltet.",
  REJECTED: "Die Anfrage wurde abgelehnt.",
};

export function PlanningWindowView({ weekKey }: { weekKey: string }) {
  const gateway = usePlanningGateway();
  const [state, setState] = useState<ViewState>({ kind: "laedt" });

  useEffect(() => {
    let abgebrochen = false;
    setState({ kind: "laedt" });
    void gateway.getPlanningWindow({ weekKey }).then((result) => {
      if (abgebrochen) return;
      setState(
        result.ok
          ? { kind: "geladen", window: result.value }
          : { kind: "fehler", failure: result.failure },
      );
    });
    return () => {
      abgebrochen = true;
    };
  }, [gateway, weekKey]);

  if (state.kind === "laedt") {
    return (
      <Card>
        <p data-testid="planungsfenster-laedt">Wochenplan wird geladen …</p>
      </Card>
    );
  }

  if (state.kind === "fehler") {
    return (
      <Card>
        <p data-testid="planungsfenster-fehler" data-failure={state.failure} role="alert">
          {FAILURE_TEXT[state.failure]}
        </p>
      </Card>
    );
  }

  const { window: fenster } = state;

  return (
    <Card>
      <h2 data-testid="planungsfenster-woche">Wochenplan {fenster.weekKey}</h2>
      <p data-testid="planungsfenster-zone">Zeitzone: {fenster.timeZone}</p>
      <p
        data-testid="planungsfenster-version"
        data-published-version-id={fenster.publishedVersionId ?? ""}
      >
        {fenster.publishedVersionId === null
          ? "Noch nicht veroeffentlicht"
          : `Veroeffentlichte Version: ${fenster.publishedVersionId}`}
      </p>

      {fenster.assignments.length === 0 ? (
        <p data-testid="planungsfenster-leer">Für diese Woche ist nichts geplant.</p>
      ) : (
        <ul data-testid="planungsfenster-liste">
          {fenster.assignments.map((assignment) => (
            <li key={assignment.id} data-assignment-id={assignment.id}>
              {assignment.interval.startUtc} – {assignment.interval.endUtc}
            </li>
          ))}
        </ul>
      )}
    </Card>
  );
}

/**
 * Zustaende des Planungsfensters (EYT-50).
 *
 * Der wichtigste Fall ist die Unterscheidung LEER vs. FEHLER. Zeigte die
 * Ansicht bei einem Ausfall eine leere Woche, laese sich der Ausfall als
 * "nichts geplant" — und genau das ist der Zustand, in dem jemand eine
 * Baustelle nicht besetzt, weil die Anzeige plausibel aussah.
 */
import type { GatewayResult, PlanningGateway, PlanningWindow } from "@easytree/contracts";
import { render, screen, waitFor } from "@testing-library/react";
import { describe, expect, it } from "vitest";

import { PlanningWindowView } from "../components/planning-window-view";
import { PlanningGatewayProvider } from "../lib/planning-gateway-provider";

function gatewayReturning(result: GatewayResult<PlanningWindow>): PlanningGateway {
  return {
    getPlanningWindow: () => Promise.resolve(result),
    validateDraft: () => {
      throw new Error("in dieser Ansicht nicht benutzt");
    },
    createAssignment: () => {
      throw new Error("in dieser Ansicht nicht benutzt");
    },
    publishPlan: () => {
      throw new Error("in dieser Ansicht nicht benutzt");
    },
  };
}

function renderWith(result: GatewayResult<PlanningWindow>): void {
  render(
    <PlanningGatewayProvider gateway={gatewayReturning(result)}>
      <PlanningWindowView weekKey="2026-W32" />
    </PlanningGatewayProvider>,
  );
}

const LEERE_WOCHE: PlanningWindow = {
  weekKey: "2026-W32",
  timeZone: "Europe/Berlin",
  assignments: [],
  publishedVersionId: null,
};

describe("PlanningWindowView", () => {
  it("zeigt zuerst den Ladezustand", () => {
    renderWith({ ok: true, value: LEERE_WOCHE });
    expect(screen.getByTestId("planungsfenster-laedt")).toBeTruthy();
  });

  it("zeigt eine leere Woche als leer, nicht als Fehler", async () => {
    renderWith({ ok: true, value: LEERE_WOCHE });
    await waitFor(() => expect(screen.getByTestId("planungsfenster-leer")).toBeTruthy());
    expect(screen.queryByTestId("planungsfenster-fehler")).toBeNull();
    expect(screen.getByTestId("planungsfenster-zone").textContent).toContain("Europe/Berlin");
  });

  it("zeigt einen Ausfall als Fehler, nicht als leere Woche", async () => {
    // Die Unterscheidung, an der alles haengt.
    renderWith({ ok: false, failure: "UNAVAILABLE", problem: null });
    await waitFor(() => expect(screen.getByTestId("planungsfenster-fehler")).toBeTruthy());
    expect(screen.queryByTestId("planungsfenster-leer")).toBeNull();
    expect(screen.getByTestId("planungsfenster-fehler").getAttribute("data-failure")).toBe(
      "UNAVAILABLE",
    );
  });

  it("meldet einen Vertragsbruch als solchen", async () => {
    // Ein Server, der 200 mit falscher Form antwortet, darf nicht als leere
    // Woche durchgehen — der Client hat ihn bereits verworfen.
    renderWith({ ok: false, failure: "CONTRACT_VIOLATION", problem: null });
    await waitFor(() =>
      expect(screen.getByTestId("planungsfenster-fehler").getAttribute("data-failure")).toBe(
        "CONTRACT_VIOLATION",
      ),
    );
  });

  it("zeigt fehlende Anmeldung als solche, nicht als leere Woche", async () => {
    renderWith({ ok: false, failure: "UNAUTHENTICATED", problem: null });
    await waitFor(() =>
      expect(screen.getByTestId("planungsfenster-fehler").getAttribute("data-failure")).toBe(
        "UNAUTHENTICATED",
      ),
    );
  });

  it("traegt die serverseitigen Ids im Markup", async () => {
    // AK9 verlangt, dass beide Ansichten DIESELBEN Ids zeigen. Ueber Text
    // waere das ein Vergleich von Darstellung; hier stehen die Ids selbst.
    renderWith({
      ok: true,
      value: {
        weekKey: "2026-W32",
        timeZone: "Europe/Berlin",
        assignments: [
          {
            id: "11111111-1111-4111-8111-111111111111",
            employeeId: "22222222-2222-4222-8222-222222222222",
            worksiteId: "33333333-3333-4333-8333-333333333333",
            interval: {
              startUtc: "2026-08-03T06:00:00.000Z",
              endUtc: "2026-08-03T14:00:00.000Z",
            },
          },
        ],
        publishedVersionId: "44444444-4444-4444-8444-444444444444",
      },
    });

    await waitFor(() => expect(screen.getByTestId("planungsfenster-liste")).toBeTruthy());
    const eintrag = screen.getByTestId("planungsfenster-liste").querySelector("li");
    expect(eintrag?.getAttribute("data-assignment-id")).toBe(
      "11111111-1111-4111-8111-111111111111",
    );
    expect(
      screen.getByTestId("planungsfenster-version").getAttribute("data-published-version-id"),
    ).toBe("44444444-4444-4444-8444-444444444444");
  });
});

